/**
 * Shared system-field classification used outside any single workflow.
 *
 * The platform auto-provisions a fixed set of system fields on every app. They
 * are identified by tags, not display names: a user may rename a field while
 * the tag keeps its platform role.
 *
 * System fields travel in the normal app `fields` list. Only Title and Status
 * can be assigned record values. Read-only deploy protection comes from the
 * backend `system` flag stored in state.
 */
/**
 * Canonical semantic-tag values the platform stamps onto its auto-provisioned
 * system fields. Union across all aspect variants.
 */
export const REQUIRED_TAG_NAMES = new Set([
    "HANDLE",
    "TITLE",
    "STATUS",
    "STAGE",
    "CREATED_AT",
    "CREATED_BY",
    "UPDATED_AT",
    "UPDATED_BY",
    "CLOSED_AT",
    "CLOSED_BY",
]);
/**
 * The subset of system tags whose fields a record-write surface may set.
 * Everything else in {@link REQUIRED_TAG_NAMES} is platform-managed and
 * read-only for record values.
 */
export const WRITABLE_SYSTEM_TAG_NAMES = new Set([
    "TITLE",
    "STATUS",
]);
export const DEFAULT_SYSTEM_FIELD_NAME_BY_TAG = {
    HANDLE: "ID",
    TITLE: "Title",
    STATUS: "Status",
    STAGE: "Stage",
    CREATED_AT: "Created on",
    CREATED_BY: "Created by",
    UPDATED_AT: "Updated on",
    UPDATED_BY: "Updated by",
    CLOSED_AT: "Closed on",
    CLOSED_BY: "Closed by",
};
export function systemFieldTag(f) {
    for (const tag of f.tags ?? f.semanticTags ?? []) {
        if (REQUIRED_TAG_NAMES.has(tag))
            return tag;
    }
    return undefined;
}
/**
 * True if the wire/state field is system-provisioned/reserved by legacy EDK
 * classification. Tags still drive role reconciliation because Title/Status
 * can come back with `system: false`.
 */
export function isSystemField(f) {
    if (f.system === true)
        return true;
    return systemFieldTag(f) !== undefined;
}
/**
 * True if the field is a writable system field: TITLE or STATUS.
 */
export function isWritableSystemField(f) {
    for (const tag of f.tags ?? f.semanticTags ?? []) {
        if (WRITABLE_SYSTEM_TAG_NAMES.has(tag))
            return true;
    }
    return false;
}
/** True for the platform-owned Stage picklist field. */
export function isStageSystemField(f) {
    return (f.tags ?? f.semanticTags ?? []).includes("STAGE");
}
/** True for backend-owned read-only system fields. */
export function isReadOnlySystemField(f) {
    return f.system === true;
}
/**
 * Canonical `systemFields` bag key → platform semantic tag. These keys are the
 * ONLY authoring/catalog identity for system fields: pulled source keys its
 * hoisted refs and overrides by them, `ref()` exposes `fields.<key>` tokens
 * under them, and the custom `fields: {}` bag rejects them as collisions.
 */
export const SYSTEM_FIELD_TAG_BY_KEY = {
    id: "HANDLE",
    title: "TITLE",
    status: "STATUS",
    stage: "STAGE",
    createdAt: "CREATED_AT",
    createdBy: "CREATED_BY",
    updatedAt: "UPDATED_AT",
    updatedBy: "UPDATED_BY",
    closedAt: "CLOSED_AT",
    closedBy: "CLOSED_BY",
};
/** All canonical keys, in platform rank order (HANDLE first … CLOSED_BY last). */
export const SYSTEM_FIELD_KEYS = Object.keys(SYSTEM_FIELD_TAG_BY_KEY);
/** `SYSTEM_FIELD_KEYS` as a set — for O(1) "is this key a system field?" checks (e.g. distinguishing a system field from a custom field by bag key alone). */
export const SYSTEM_FIELD_KEY_SET = new Set(SYSTEM_FIELD_KEYS);
export const SYSTEM_FIELD_KEY_BY_TAG = Object.fromEntries(Object.entries(SYSTEM_FIELD_TAG_BY_KEY).map(([k, tag]) => [tag, k]));
/** Internal Terraform map key for each public `systemFields` key. */
export const SYSTEM_FIELD_HCL_KEY_BY_KEY = {
    id: "id",
    title: "title",
    status: "status",
    stage: "stage",
    createdAt: "created_at",
    createdBy: "created_by",
    updatedAt: "updated_at",
    updatedBy: "updated_by",
    closedAt: "closed_at",
    closedBy: "closed_by",
};
/** Internal inverse used only at the HCL extraction boundary. */
export const SYSTEM_FIELD_KEY_BY_HCL_KEY = Object.fromEntries(Object.entries(SYSTEM_FIELD_HCL_KEY_BY_KEY).map(([key, hclKey]) => [hclKey, key]));
/**
 * What a NO-OVERRIDE deploy produces — the terraform provider's auto-create
 * display names. This is the baseline the pull printer compares against when
 * deciding whether a live system field warrants a `systemFields` entry.
 *
 * Deliberately a separate table from {@link DEFAULT_SYSTEM_FIELD_NAME_BY_TAG}:
 * the platform's own compose defaults use "Created on"/"Updated on"/"Closed
 * on", but the provider creates "Created At"/"Updated At"/"Closed At" (and
 * "Created By" etc. with a capital B). An app that came through EDK/terraform
 * therefore round-trips clean against THIS table, while a platform-composed
 * app surfaces its "Created on"-style names as explicit overrides.
 */
export const DEPLOY_DEFAULT_SYSTEM_FIELD_NAMES = {
    id: "ID",
    title: "Title",
    status: "Status",
    stage: "Stage",
    createdAt: "Created At",
    createdBy: "Created By",
    updatedAt: "Updated At",
    updatedBy: "Updated By",
    closedAt: "Closed At",
    closedBy: "Closed By",
};
/**
 * The status options a no-override deploy produces (the provider's
 * `getDefaultStatusOptions` labels, filled when `status_options` is empty).
 * The pull baseline for `systemFields.status.options`; colors/option-tags are
 * platform cosmetics EDK doesn't model (the HCL fold emits labels only).
 */
export const DEPLOY_DEFAULT_STATUS_OPTIONS = ["Open", "In Progress", "Closed"];
/** Provider HCL values for the status options created by the platform baseline. */
export const DEPLOY_DEFAULT_STATUS_OPTION_VALUES = [
    { label: "Open", color: "#3B82F6", tags: [] },
    { label: "In Progress", color: "#F59E0B", tags: [] },
    { label: "Closed", color: "#10B981", tags: ["CLOSED"] },
];
/**
 * Whether the provider marks the auto-created field `required` — synthesized
 * into the compose payload so the wire shape matches what terraform creates.
 */
export const SYSTEM_FIELD_REQUIRED = {
    id: true,
    title: true,
    status: false,
    stage: false,
    createdAt: true,
    createdBy: true,
    updatedAt: true,
    updatedBy: true,
    closedAt: false,
    closedBy: false,
};
